    c=Counter(v for r in g for v in r)
    p=f=c.most_common(2)[0][0]; fill=c.most_common(2)[1][0]
    rare={v for v in set(c)-{p,fill}}
    mr=[r for r in range(H) if any(g[r][cc] in rare for cc in range(W))]
    mc=[cc for cc in range(W) if any(g[rr][cc] in rare for rr in range(H))]
